/**
 * Resolves the application origin without guessing Vercel's generated host.
 *
 * The payments QA Preview uses Vercel's branch URL system variable because
 * that hostname is generated by Vercel for the current deployment and may be
 * truncated. QA context is deliberately exact and fails closed if identity,
 * URL, or an explicit origin override is missing or inconsistent.
 */

export const PAYMENTS_QA_PROJECT_ID = 'prj_dhm3g8xGGRQaPbpcgQmQwnSe7qU2';
export const PAYMENTS_QA_BRANCH = 'codex/payments-reconstruction-20261106';

const PAYMENTS_QA_BRANCH_HOST_PREFIX = 'fine-diet-payments-qa-target-git-';

function isPaymentsQaBranchUrl(value: string | undefined): boolean {
  const hostname = value?.toLowerCase();
  return Boolean(
    hostname?.startsWith(PAYMENTS_QA_BRANCH_HOST_PREFIX) &&
    hostname.endsWith('.vercel.app'),
  );
}

export interface SiteOriginContext {
  explicitSiteUrl?: string;
  serverSiteUrl?: string;
  requestOrigin?: string;
  browserOrigin?: string;
  vercelProjectId?: string;
  vercelEnvironment?: string;
  vercelGitBranch?: string;
  vercelBranchUrl?: string;
  publicVercelEnvironment?: string;
  publicVercelProjectId?: string;
  publicVercelGitBranch?: string;
  publicVercelBranchUrl?: string;
}

export class SiteOriginError extends Error {
  constructor(code: string) {
    super(`Site origin resolution failed [${code}]`);
    this.name = 'SiteOriginError';
  }
}

function parseConfiguredOrigin(value: string): string {
  let url: URL;
  try {
    url = new URL(value.trim());
  } catch {
    throw new SiteOriginError('EXPLICIT_ORIGIN_INVALID');
  }

  if (
    url.protocol !== 'https:' ||
    url.username ||
    url.password ||
    url.port ||
    (url.pathname !== '' && url.pathname !== '/') ||
    url.search ||
    url.hash
  ) {
    throw new SiteOriginError('EXPLICIT_ORIGIN_INVALID');
  }

  return url.origin;
}

function resolveGeneratedBranchOrigin(
  branchUrl: string | undefined,
  explicitSiteUrl?: string,
  serverSiteUrl?: string,
): string {
  if (!branchUrl) throw new SiteOriginError('BRANCH_URL_MISSING');

  let url: URL;
  try {
    // Vercel supplies the branch URL as a hostname without a scheme.
    url = new URL(`https://${branchUrl}`);
  } catch {
    throw new SiteOriginError('BRANCH_URL_INVALID');
  }

  const hostname = url.hostname.toLowerCase();
  if (
    url.protocol !== 'https:' ||
    url.username ||
    url.password ||
    url.port ||
    url.pathname !== '/' ||
    url.search ||
    url.hash ||
    url.host !== branchUrl ||
    !hostname.startsWith(PAYMENTS_QA_BRANCH_HOST_PREFIX) ||
    !hostname.endsWith('.vercel.app')
  ) {
    throw new SiteOriginError('BRANCH_URL_INVALID');
  }

  const origin = url.origin;
  for (const configured of [explicitSiteUrl, serverSiteUrl]) {
    if (!configured?.trim()) continue;
    if (parseConfiguredOrigin(configured) !== origin) {
      throw new SiteOriginError('EXPLICIT_ORIGIN_CONFLICT');
    }
  }

  return origin;
}

/** Pure resolver kept separate from process.env for focused identity tests. */
export function resolveSiteOrigin(context: SiteOriginContext): string | undefined {
  const serverIdentityPresent = Boolean(
    context.vercelProjectId || context.vercelEnvironment || context.vercelGitBranch || context.vercelBranchUrl,
  );
  const publicIdentityPresent = Boolean(
    context.publicVercelProjectId || context.publicVercelEnvironment ||
    context.publicVercelGitBranch || context.publicVercelBranchUrl,
  );
  const serverQaIdentity =
    context.vercelProjectId === PAYMENTS_QA_PROJECT_ID ||
    context.vercelGitBranch === PAYMENTS_QA_BRANCH ||
    isPaymentsQaBranchUrl(context.vercelBranchUrl);
  const publicQaIdentity =
    context.publicVercelProjectId === PAYMENTS_QA_PROJECT_ID ||
    context.publicVercelGitBranch === PAYMENTS_QA_BRANCH ||
    isPaymentsQaBranchUrl(context.publicVercelBranchUrl);
  const serverQaSignal = serverQaIdentity || (publicQaIdentity && serverIdentityPresent);
  const publicQaSignal = publicQaIdentity || (serverQaIdentity && publicIdentityPresent);

  let serverOrigin: string | undefined;
  if (serverQaSignal) {
    if (
      context.vercelProjectId !== PAYMENTS_QA_PROJECT_ID ||
      context.vercelEnvironment !== 'preview' ||
      context.vercelGitBranch !== PAYMENTS_QA_BRANCH
    ) {
      throw new SiteOriginError('SERVER_CONTEXT_MISMATCH');
    }

    serverOrigin = resolveGeneratedBranchOrigin(
      context.vercelBranchUrl,
      context.explicitSiteUrl,
      context.serverSiteUrl,
    );
  }

  let publicOrigin: string | undefined;
  if (publicQaSignal) {
    if (
      context.publicVercelProjectId !== PAYMENTS_QA_PROJECT_ID ||
      context.publicVercelEnvironment !== 'preview' ||
      context.publicVercelGitBranch !== PAYMENTS_QA_BRANCH
    ) {
      throw new SiteOriginError('PUBLIC_CONTEXT_MISMATCH');
    }

    publicOrigin = resolveGeneratedBranchOrigin(
      context.publicVercelBranchUrl,
      context.explicitSiteUrl,
    );
  }

  if (serverOrigin && publicOrigin && serverOrigin !== publicOrigin) {
    throw new SiteOriginError('SERVER_PUBLIC_CONTEXT_MISMATCH');
  }
  if (serverOrigin || publicOrigin) return serverOrigin || publicOrigin;

  // Partial identity on the dedicated project must never reach a configured
  // Production or localhost fallback.
  if (context.vercelProjectId === PAYMENTS_QA_PROJECT_ID) {
    throw new SiteOriginError('SERVER_CONTEXT_MISMATCH');
  }

  const configured = context.explicitSiteUrl?.trim();
  if (configured) return configured.replace(/\/+$/, '');

  const serverConfigured = context.serverSiteUrl?.trim();
  if (serverConfigured) return serverConfigured.replace(/\/+$/, '');

  return context.browserOrigin || context.requestOrigin;
}

export function resolveSiteUrl(
  path: string,
  context: SiteOriginContext,
): string | undefined {
  const origin = resolveSiteOrigin(context);
  if (!origin) return undefined;
  return new URL(path.startsWith('/') ? path : `/${path}`, `${origin}/`).toString();
}

/**
 * Environment-aware resolver. NEXT_PUBLIC_* references are direct so Next.js
 * can inline Vercel's framework variables into browser bundles at build time.
 */
function getSiteOriginContext(options: {
  requestOrigin?: string;
  includeServerSiteUrl?: boolean;
} = {}): SiteOriginContext {
  const browserOrigin =
    typeof window !== 'undefined' ? window.location.origin : undefined;

  return {
    explicitSiteUrl: process.env.NEXT_PUBLIC_SITE_URL,
    serverSiteUrl: options.includeServerSiteUrl ? process.env.SITE_URL : undefined,
    requestOrigin: options.requestOrigin,
    browserOrigin,
    vercelProjectId: process.env.VERCEL_PROJECT_ID,
    vercelEnvironment: process.env.VERCEL_ENV,
    vercelGitBranch: process.env.VERCEL_GIT_COMMIT_REF,
    vercelBranchUrl: process.env.VERCEL_BRANCH_URL,
    publicVercelEnvironment: process.env.NEXT_PUBLIC_VERCEL_ENV,
    publicVercelProjectId: process.env.NEXT_PUBLIC_VERCEL_PROJECT_ID,
    publicVercelGitBranch: process.env.NEXT_PUBLIC_VERCEL_GIT_COMMIT_REF,
    publicVercelBranchUrl: process.env.NEXT_PUBLIC_VERCEL_BRANCH_URL,
  };
}

export function getSiteOrigin(options: {
  requestOrigin?: string;
  includeServerSiteUrl?: boolean;
} = {}): string | undefined {
  return resolveSiteOrigin(getSiteOriginContext(options));
}

export function resolveSiteOriginOrDefault(
  context: SiteOriginContext,
  defaultOrigin: string,
): string {
  return resolveSiteOrigin(context) ?? defaultOrigin;
}

export function getSiteOriginOrDefault(
  defaultOrigin: string,
  options: { requestOrigin?: string; includeServerSiteUrl?: boolean } = {},
): string {
  return resolveSiteOriginOrDefault(getSiteOriginContext(options), defaultOrigin);
}

export function getSiteUrl(
  path: string,
  options: { requestOrigin?: string; includeServerSiteUrl?: boolean } = {},
): string {
  const resolved = resolveSiteUrl(path, getSiteOriginContext(options));
  if (resolved) return resolved;
  return new URL(path.startsWith('/') ? path : `/${path}`, 'http://localhost:3000/').toString();
}

/** Preserve Stripe's historical base-plus-path concatenation semantics. */
export function resolveAbsoluteSiteUrl(path: string, context: SiteOriginContext): string {
  const base = resolveSiteOrigin(context) ?? 'http://localhost:3000';
  return `${base.replace(/\/$/, '')}${path}`;
}

export function getAbsoluteSiteUrl(
  path: string,
  options: { requestOrigin?: string; includeServerSiteUrl?: boolean } = {},
): string {
  return resolveAbsoluteSiteUrl(path, getSiteOriginContext(options));
}
